def shapekey(cells):
    ys=[y for y,x in cells]; xs=[x for y,x in cells]
    return tuple(sorted((y-min(ys),x-min(xs)) for y,x in cells))

def norm_rot(cells):
    # canonical form over 4 rotations (+ maybe mirror)
    def mk(c):
        ys=[y for y,x in c]; xs=[x for y,x in c]
        return tuple(sorted((y-min(ys),x-min(xs)) for y,x in c))
    c=list(cells)
    best=[]
    cur=c
    for _ in range(4):
        best.append(mk(cur))
        cur=[(x,-y) for y,x in cur]
    return set(best)

