import numpy as np
from scipy import ndimage
from collections import defaultdict
def comps(g):
    g=np.array(g); out=[]
    cnt=np.bincount(g.ravel()); bg=cnt.argmax()
    for c in np.unique(g):
        if c==bg: continue
        lab,n=ndimage.label(g==c)
        for i in range(1,n+1):
            out.append((int(c),[tuple(x) for x in np.argwhere(lab==i)]))
    return out
